  stats.xG += shot.xG;
  if (shot.onTarget) stats.shotsOnTarget += 1;
  if (shot.goal) stats.goals += 1;
  if (shot.corner) stats.corners += 1;
  if (shot.save) ctx.state.stats[defending.side].saves += 1;
  if (shot.eventType === "SHOT_POST" /* SHOT_POST */) stats.posts += 1;
