    nextPossessionReason: shot.goal ? "GOAL_RESTART" : shot.corner ? "CORNER" : shot.save ? "SAVE" : "GOAL_KICK",
    restartSourceEventId: shot.corner ? events.at(-1)?.id : setPieceShotId,
